use vstd::prelude::*;

verus! {

fn concatenate(a: Vec<f32>, b: Vec<f32>) -> (out: Vec<f32>)
    requires
        // Prevent overflow in `with_capacity(a.len() + b.len())`
        a.len() <= usize::MAX - b.len(),
    ensures
        out.len() == a.len() + b.len(),
{
    let mut out = Vec::with_capacity(a.len() + b.len());

    out.extend(a);
    assert(out.len() == a.len());

    out.extend(b);
    assert(out.len() == a.len() + b.len());

    out
}

}

